# Reconstruct and print suspicious > 180 min rows all carriers
for f in glob.glob('airlines/*.csv'):
 car=os.path.basename(f)[:2]; d=pd.read_csv(f).drop_duplicates('flight_id').copy(); d['cancelled']=d.cancelled.astype(bool)
 if 'date_utc' in d:
  d['s']=pd.to_datetime(d.date_utc+' '+d.sched_dep_utc); d['a']=pd.to_datetime(d.date_utc+' '+d.actual_dep_utc,errors='coerce')
 else: d['s']=pd.to_datetime(d.date+' '+d.sched_dep); d['a']=pd.to_datetime(d.date+' '+d.actual_dep,errors='coerce')
 raw=(d.a-d.s).dt.total_seconds()/60
 x=d[(~d.cancelled)&raw.lt(-180)]
 print(car, x[['flight_id','date' if 'date' in d else 'date_utc','sched_dep' if 'sched_dep' in d else 'sched_dep_utc','actual_dep' if 'actual_dep' in d else 'actual_dep_utc']].assign(raw=raw[x.index]).to_string(index=False))

results={}
for f in glob.glob('airlines/*.csv'):
 car=os.path.basename(f)[:2]; d=pd.read_csv(f).drop_duplicates('flight_id').copy(); d.cancelled=d.cancelled.astype(bool)
 if 'date_utc' in d:
  s=pd.to_datetime(d.date_utc+' '+d.sched_dep_utc); a=pd.to_datetime(d.date_utc+' '+d.actual_dep_utc,errors='coerce'); offs=d.origin.map(air.set_index('airport').utc_offset_hours); local=s+pd.to_timedelta(offs,unit='h')
 else:
  s=pd.to_datetime(d.date+' '+d.sched_dep); a=pd.to_datetime(d.date+' '+d.actual_dep,errors='coerce'); local=s
 raw=(a-s).dt.total_seconds()/60
 a=a.mask(raw < -180, a+pd.Timedelta(days=1))
 delay=(a-s).dt.total_seconds()/60
 feb=d[local.dt.to_period('M')==pd.Period('2025-02')].copy(); feb['delay']=delay.loc[feb.index]
 comp=feb[~feb.cancelled]; n=(comp.delay>15).sum(); den=len(comp)
 results[car]={'flights':len(feb),'completed':den,'delayed':int(n),'rate':n/den*100}
 print(car, results[car], 'range',comp.delay.min(),comp.delay.max())
